package com.projecteden.title.controller;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.title.dto.*;import com.projecteden.title.service.TitleService;import com.projecteden.user.domain.User;import jakarta.validation.Valid;@RestController@RequestMapping("/api/titles")public class TitleController{private final TitleService service;public TitleController(TitleService service){this.service=service;}@GetMapping("/me")public List<TitleResponse> get(@AuthenticationPrincipal User user){return service.getMyTitles(user.getId());}@PutMapping("/me/active")public TitleResponse active(@AuthenticationPrincipal User user,@Valid @RequestBody SetActiveTitleRequest request){return service.setActiveTitle(user.getId(),request.titleCode());}}
